-- GENERATED by tools/gamekit/bundle.py from tools/gamekit/gamekit.lua and apps/hashi/src/
-- -- edit those files, not this one.
local kit = (function()
-- gamekit: shared pieces for the API 2.9 puzzle games (Lights Out, Peg Solitaire, Nonograms,
-- Knight's Tour). tools/gamekit/bundle.py puts it in front of a game's src/main.lua as
-- `local kit = (function() ... end)()`, since the device has no require for package files.
--
--   kit.W, kit.H                      screen size
--   kit.font(name), kit.width(f, s), kit.line_h(name)
--   kit.short(s, n), kit.drop_last(s), kit.wrap(s, fname, maxw)
--   kit.read(name), kit.write(name, s), kit.kv(s)   ctx.storage helpers ("key=value" lines)
--   kit.now_ms(), kit.refresh()
--   kit.moved()                       count a move (a hook for a periodic full refresh; see below)
--   kit.key_accepted(ev)              side buttons send several events per press: keep one
--   kit.show(m), kit.close(), kit.modal()   a box over the screen: { title, lines, rows, cancel },
--                                     rows = { { {label, fn, enabled}, .. }, .. }
--   kit.draw_modal(gg), kit.tap_modal(x, y) -> true when the box took the tap
--   kit.button(gg, x, y, w, h, label, opts)  a framed button with a centred label
-- Every ctx.* function is a method on this API: colon calls everywhere. Nothing is filled black:
-- large black areas ghost on e-ink, and the host draws text black even when asked for white.

local kit = {}
kit.W, kit.H = 480, 800

function kit.font(name) return ctx.fonts and ctx.fonts[name] end
function kit.width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
function kit.line_h(name)
  local ok, h = pcall(function() return kit.font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- drop the last character (a whole UTF-8 sequence)
function kit.drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
function kit.short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = kit.drop_last(t) end
  return t .. '~'
end
-- word wrap on ASCII spaces only (%s may also match 0xA0, the second byte of some letters)
function kit.wrap(s, fname, maxw)
  local f, out = kit.font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for word in para:gmatch('[^ \t]+') do
      local cand = line == '' and word or (line .. ' ' .. word)
      if line ~= '' and kit.width(f, cand) > maxw then out[#out + 1] = line; line = word else line = cand end
    end
    out[#out + 1] = line
  end
  return out
end

function kit.read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
function kit.write(name, s) pcall(function() ctx.storage:write(name, s) end) end
function kit.kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

function kit.now_ms() local ok, t = pcall(function() return ctx.clock:millis() end); return ok and tonumber(t) or nil end
function kit.refresh() pcall(function() ctx:invalidate() end) end

-- e-ink full refresh: API 0.8 had ctx.display:full_refresh(); API 2.9 only offers
-- ctx:defer_full_refresh(n), which on the device (26102401) did not trigger one, and which by its
-- name may rather postpone the host's own periodic refresh. So nothing is asked for: the games
-- showed no ghosting problem without it. kit.moved() stays as the place to add one.
local moves = 0
function kit.moved() moves = moves + 1 end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
function kit.key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local t = tonumber(ev.time_ms) or kit.now_ms()
  if t and last_key == ev.key and last_key_ms and t - last_key_ms >= 0 and t - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, t
  return true
end

------------------------------------------------------------------ boxes

local BOX_X, ROW_H, GAP = 20, 56, 10
local BOX_W = kit.W - 40      -- refreshed in layout(): an app may set kit.W, kit.H for a landscape screen
local modal = nil

function kit.show(m) modal = m end
function kit.close() modal = nil end
function kit.modal() return modal end

local function layout(m)
  BOX_W = kit.W - 40
  local lines = {}
  if m.title then for _k, l in ipairs(kit.wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end end
  for _k, s in ipairs(m.lines or {}) do
    for _j, l in ipairs(kit.wrap(s, 'small', BOX_W - 40)) do lines[#lines + 1] = { l, 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + kit.line_h(l[2]) + 4 end
  local h = 20 + th + 14 + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(60, math.floor((kit.H - h) / 2))
  local btns, by = {}, y + 20 + th + 14
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h
end

function kit.button(gg, x, y, w, h, label, opts)
  opts = opts or {}
  local f = kit.font(opts.font or 'medium')
  gg:rect(x, y, w, h, { line_width = opts.line_width or 2 })
  local s = tostring(label)
  while #s > 1 and kit.width(f, s) > w - 10 do s = kit.drop_last(s) end
  gg:text(x + math.floor((w - kit.width(f, s)) / 2), y + math.floor((h - kit.line_h(opts.font or 'medium')) / 2), s, { font = f })
end

function kit.draw_modal(gg)
  local lines, btns, y, h = layout(modal)
  -- paper first, so the page under the box does not show through it
  gg:rect(BOX_X, y, BOX_W, h, { fill = true, color = 0 })
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = kit.font(l[2]) }); ty = ty + kit.line_h(l[2]) + 4 end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    kit.button(gg, bt.x, bt.y, bt.w, bt.h, enabled and bt.b[1] or ('(' .. bt.b[1] .. ')'), { line_width = enabled and 2 or 1 })
  end
end

function kit.tap_modal(x, y)
  if not modal then return false end
  local _l, btns, my, mh = layout(modal)
  for _k, bt in ipairs(btns) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
      if bt.b[3] ~= false then bt.b[2]() end
      return true
    end
  end
  if (y < my or y > my + mh) and modal.cancel then modal.cancel() end
  return true
end

return kit
end)()

-- Hashi (Bridges) for XTOS Licorice, API 2.0 (uses tools/gamekit).
--
-- Connect the islands with bridges: each island's number is how many bridges end there, two
-- islands share at most two bridges, bridges run straight across the water and never cross, and
-- in the end every island is reached from every other. The banks (make_bank.py) hold puzzles
-- with one solution, reached by reasoning; a line is n*n characters ('.' water, '1'..'8' an
-- island), every line of a bank the same length, so puzzle N is a seek away.
--
-- Tap the water between two islands to add a bridge: none, one, two, none again. Or tap an
-- island, then another in line with it. A full island gets a second ring; one with too many
-- bridges is crossed. Undo, Restart, Next, and More (levels, previous puzzle, how to play).

local W, H = kit.W, kit.H
local GRID_Y, GRID_W = 92, 456
local STATUS_Y = 680
local BTN_Y, BTN_H = 740, 50
local LEVELS = { ['7x7-easy'] = 'Easy 7x7', ['9x9-medium'] = 'Medium 9x9', ['11x11-hard'] = 'Hard 11x11' }

local banks = {}         -- { file, label, count, stride }
local bank = nil         -- the current bank
local idx = 1
local grid = nil         -- { n, need = { [cell] = number }, isl = { cells }, edges = { {a, b, horizontal} }, cross }
local bridges = {}       -- edge -> 0, 1 or 2
local undo_stack = {}
local sel = nil          -- a tapped island
local solved = false
local done = {}          -- bank file -> { [idx] = true }
local places = {}        -- bank file -> the puzzle last played
local msg = nil
local ERR = nil

------------------------------------------------------------------ data

local function open_text(name)
  local P = ctx.package
  if not P then return nil end
  local ok, r = pcall(function() return P:open_text(name, { max_line_bytes = 512 }) end)
  if ok and r ~= nil and type(r) ~= 'string' then return r end
  return nil
end

local function load_banks()
  banks = {}
  local r = open_text('banks.tsv')
  if not r then return end
  while true do
    local ok, line = pcall(function() return r:read_line() end)
    if not ok or line == nil then break end
    local file, count, stride, label = line:match('^([^\t]+)\t(%d+)\t(%d+)\t?([^\t]*)')
    if file and tonumber(count) > 0 then
      banks[#banks + 1] = { file = file, label = LEVELS[label] or label, count = tonumber(count), stride = tonumber(stride) }
    end
  end
  pcall(function() r:close() end)
  -- smallest grid first: 7x7, 9x9, 11x11
  table.sort(banks, function(a, b) return (tonumber(a.file:match('^%d+')) or 0) < (tonumber(b.file:match('^%d+')) or 0) end)
end

local function read_line(b, n)
  local r = open_text(b.file)
  if not r then return nil end
  local line
  pcall(function()
    if b.stride > 0 then r:seek((n - 1) * b.stride); line = r:read_line()
    else for _k = 1, n do line = r:read_line() end end
  end)
  pcall(function() r:close() end)
  return line
end

-- a bank line -> the puzzle: islands, and the edges between islands in line of sight
local function parse(line)
  if type(line) ~= 'string' then return nil end
  local n = math.floor(math.sqrt(#line) + 0.5)
  if n < 4 or n * n ~= #line or line:find('[^%.1-8]') then return nil end
  local g = { n = n, need = {}, isl = {}, edges = {}, at = {} }
  for i = 1, n * n do
    local ch = line:sub(i, i)
    if ch ~= '.' then g.need[i] = tonumber(ch); g.isl[#g.isl + 1] = i end
  end
  for _k, i in ipairs(g.isl) do
    local r, c = (i - 1) // n, (i - 1) % n
    for _d, dir in ipairs({ { 0, 1, true }, { 1, 0, false } }) do
      local rr, cc, gap = r + dir[1], c + dir[2], 0
      while rr < n and cc < n and not g.need[rr * n + cc + 1] do rr, cc, gap = rr + dir[1], cc + dir[2], gap + 1 end
      if rr < n and cc < n and gap > 0 then
        g.edges[#g.edges + 1] = { a = i, b = rr * n + cc + 1, h = dir[3] }
      end
    end
  end
  -- the edges that cross each other
  g.cross = {}
  for e, x in ipairs(g.edges) do
    g.cross[e] = {}
    for f, y in ipairs(g.edges) do
      if x.h and not y.h then
        local xr, xc0, xc1 = (x.a - 1) // n, (x.a - 1) % n, (x.b - 1) % n
        local yc, yr0, yr1 = (y.a - 1) % n, (y.a - 1) // n, (y.b - 1) // n
        if yc > xc0 and yc < xc1 and xr > yr0 and xr < yr1 then g.cross[e][#g.cross[e] + 1] = f end
      elseif y.h and not x.h then
        local yr, yc0, yc1 = (y.a - 1) // n, (y.a - 1) % n, (y.b - 1) % n
        local xc, xr0, xr1 = (x.a - 1) % n, (x.a - 1) // n, (x.b - 1) // n
        if xc > yc0 and xc < yc1 and yr > xr0 and yr < xr1 then g.cross[e][#g.cross[e] + 1] = f end
      end
    end
  end
  return g
end

------------------------------------------------------------------ rules

local function count_at(i)
  local s = 0
  for e, x in ipairs(grid.edges) do if x.a == i or x.b == i then s = s + (bridges[e] or 0) end end
  return s
end

local function all_connected()
  local adj = {}
  for e, x in ipairs(grid.edges) do
    if (bridges[e] or 0) > 0 then
      adj[x.a] = adj[x.a] or {}; adj[x.b] = adj[x.b] or {}
      adj[x.a][#adj[x.a] + 1] = x.b; adj[x.b][#adj[x.b] + 1] = x.a
    end
  end
  local first = grid.isl[1]
  local seen, stack, n = { [first] = true }, { first }, 1
  while #stack > 0 do
    local x = table.remove(stack)
    for _k, y in ipairs(adj[x] or {}) do
      if not seen[y] then seen[y] = true; n = n + 1; stack[#stack + 1] = y end
    end
  end
  return n == #grid.isl
end

local function check_solved()
  for _k, i in ipairs(grid.isl) do if count_at(i) ~= grid.need[i] then return false end end
  return all_connected()
end

------------------------------------------------------------------ storage

local function bridge_string()
  local t = {}
  for e = 1, #grid.edges do t[e] = tostring(bridges[e] or 0) end
  return table.concat(t)
end

local function save()
  local t = { 'bank=' .. (bank and bank.file or ''), 'idx=' .. idx, 'cur=' .. (grid and bridge_string() or '') }
  for f, set in pairs(done) do
    local l = {}
    for k in pairs(set) do l[#l + 1] = k end
    table.sort(l)
    t[#t + 1] = 'done_' .. f:gsub('[^%w]', '_') .. '=' .. table.concat(l, ',')
  end
  for f, k in pairs(places) do t[#t + 1] = 'at_' .. f:gsub('[^%w]', '_') .. '=' .. k end
  kit.write('hashi.txt', table.concat(t, '\n'))
end

local function key_of(f) return (f:gsub('[^%w]', '_')) end

------------------------------------------------------------------ puzzles

local function open_puzzle(b, n, keep)
  if not b then return end
  n = (n - 1) % b.count + 1
  local g = parse(read_line(b, n))
  if not g then ERR = 'could not read puzzle ' .. n .. ' of ' .. b.file; return end
  bank, idx, grid = b, n, g
  places[b.file] = n
  bridges, undo_stack, sel, msg = {}, {}, nil, nil
  if keep and #keep == #g.edges then
    for e = 1, #g.edges do bridges[e] = tonumber(keep:sub(e, e)) or 0 end
  end
  solved = check_solved()
  if solved then msg = 'Solved!  Next for another.' end
  pcall(function() ctx:invalidate('full') end)
end

local function load_saved()
  local s = kit.kv(kit.read('hashi.txt'))
  for _k, b in ipairs(banks) do
    local set = {}
    for k in (s['done_' .. key_of(b.file)] or ''):gmatch('%d+') do set[tonumber(k)] = true end
    done[b.file] = set
    places[b.file] = tonumber(s['at_' .. key_of(b.file)])
  end
  local b = banks[1]
  for _k, x in ipairs(banks) do if x.file == s.bank then b = x end end
  open_puzzle(b, tonumber(s.idx) or places[b and b.file or ''] or 1, s.cur)
end

------------------------------------------------------------------ play

local function set_bridge(e, v)
  if solved then return end
  if v > 0 and (bridges[e] or 0) == 0 then
    for _k, f in ipairs(grid.cross[e]) do
      if (bridges[f] or 0) > 0 then msg = 'Bridges cannot cross.'; return end
    end
  end
  undo_stack[#undo_stack + 1] = { e, bridges[e] or 0 }
  bridges[e] = v
  msg = nil
  if check_solved() then
    solved = true
    done[bank.file][idx] = true
    msg = 'Solved!  Next for another.'
  end
  kit.moved()
  save()
end

local function cycle(e) set_bridge(e, ((bridges[e] or 0) + 1) % 3) end

local function undo()
  local u = table.remove(undo_stack)
  if not u then return end
  bridges[u[1]] = u[2]
  solved, msg = false, nil
  save()
end

local function restart()
  bridges, undo_stack, solved, sel, msg = {}, {}, false, nil, nil
  save()
end

------------------------------------------------------------------ geometry

local function cell_px() return GRID_W // grid.n end
local function origin() return (W - grid.n * cell_px()) // 2, GRID_Y end
local function center(i)
  local C = cell_px()
  local x0, y0 = origin()
  local r, c = (i - 1) // grid.n, (i - 1) % grid.n
  return x0 + c * C + C // 2, y0 + r * C + C // 2
end
-- islands fill more of a small cell, so the numbers stay clear of the ring on 11 x 11
local function radius() return math.floor(cell_px() * (cell_px() < 50 and 0.45 or 0.38)) end

-- the edge whose stretch of water holds the point, or nil
local function edge_at(x, y)
  local C = cell_px()
  local best, bd = nil, C
  for e, ed in ipairs(grid.edges) do
    local ax, ay = center(ed.a)
    local bx, by = center(ed.b)
    local d
    if ed.h and x > ax + radius() // 2 and x < bx - radius() // 2 then d = math.abs(y - ay)
    elseif not ed.h and y > ay + radius() // 2 and y < by - radius() // 2 then d = math.abs(x - ax) end
    if d and d < C // 2 and d < bd then best, bd = e, d end
  end
  return best
end

local function island_at(x, y)
  for _k, i in ipairs(grid.isl) do
    local cx, cy = center(i)
    if (x - cx) * (x - cx) + (y - cy) * (y - cy) <= (radius() + 6) * (radius() + 6) then return i end
  end
  return nil
end

------------------------------------------------------------------ drawing

local BUTTONS = { 'Undo', 'Restart', 'Next', 'More' }
local function button_rect(k)
  local bw = (W - 24 - 3 * 8) // 4
  return 12 + (k - 1) * (bw + 8), BTN_Y, bw, BTN_H
end

local function solved_count(b)
  local n = 0
  for _k in pairs(done[b.file] or {}) do n = n + 1 end
  return n
end

local function draw_grid(gg)
  local C, R = cell_px(), radius()
  local x0, y0 = origin()
  -- a dot in each stretch of water, so the rows and columns can be followed
  for i = 1, grid.n * grid.n do
    if not grid.need[i] then
      local cx, cy = center(i)
      gg:rect(cx - 1, cy - 1, 3, 3, { fill = true })
    end
  end
  for e, ed in ipairs(grid.edges) do
    local v = bridges[e] or 0
    if v > 0 then
      local ax, ay = center(ed.a)
      local bx, by = center(ed.b)
      if ed.h then
        ax, bx = ax + R, bx - R
        if v == 1 then gg:line(ax, ay, bx, by, { line_width = 3 })
        else gg:line(ax, ay - 5, bx, by - 5, { line_width = 3 }); gg:line(ax, ay + 5, bx, by + 5, { line_width = 3 }) end
      else
        ay, by = ay + R, by - R
        if v == 1 then gg:line(ax, ay, bx, by, { line_width = 3 })
        else gg:line(ax - 5, ay, bx - 5, by, { line_width = 3 }); gg:line(ax + 5, ay, bx + 5, by, { line_width = 3 }) end
      end
    end
  end
  local f = grid.n <= 9 and 'large' or 'medium'
  local font = kit.font(f)
  for _k, i in ipairs(grid.isl) do
    local cx, cy = center(i)
    gg:circle(cx, cy, R, { fill = true, color = 0 })
    gg:circle(cx, cy, R, { line_width = 2 })
    local have, need = count_at(i), grid.need[i]
    if have == need then gg:circle(cx, cy, R - 4, { line_width = cell_px() < 50 and 1 or 2 }) end
    if i == sel then gg:circle(cx, cy, R + 4, { line_width = 2 }) end
    local s = tostring(need)
    gg:text(cx - kit.width(font, s) // 2, cy - kit.line_h(f) // 2, s, { font = font })
    if have > need then
      gg:line(cx + R - 8, cy - R - 2, cx + R + 4, cy - R + 10, { line_width = 2 })
      gg:line(cx + R + 4, cy - R - 2, cx + R - 8, cy - R + 10, { line_width = 2 })
    end
  end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    gg:text(12, 12, 'Hashi', { font = kit.font('large') })
    if bank then
      gg:text(12, 52, kit.short(bank.label .. '   No. ' .. idx .. ' of ' .. bank.count .. '   solved ' .. solved_count(bank), 46), { font = kit.font('small') })
    end
    if kit.modal() then kit.draw_modal(gg); return end
    if grid then draw_grid(gg) end
    local small = kit.font('small')
    if msg then gg:text(12, STATUS_Y, kit.short(msg, 46), { font = small })
    elseif grid and not solved then gg:text(12, STATUS_Y, 'Tap the water between two islands.', { font = small }) end
    for k, b in ipairs(BUTTONS) do
      local x, y, bw, bh = button_rect(k)
      kit.button(gg, x, y, bw, bh, b)
    end
    if ERR then gg:text(12, H - 24, kit.short('ERR ' .. ERR, 48), { font = small }) end
  end)
  if not ok then pcall(function() gg:text(8, H - 60, kit.short('draw ERR ' .. tostring(e), 46)) end) end
end

------------------------------------------------------------------ input

local function how_to()
  kit.show({ title = 'How to play', lines = {
    "Each island's number is how many bridges end there. Two islands share one or two bridges at most; bridges run straight and never cross. In the end every island must be reached from every other.",
    'Tap the water between two islands: one bridge, two, none. Or tap an island, then another in line. A full island gets a second ring.',
  }, rows = { { { 'Close', kit.close } } }, cancel = kit.close })
end

local function more()
  local rows = {}
  local row = {}
  for _k, b in ipairs(banks) do
    row[#row + 1] = { b.label:match('^%S+'), function() kit.close(); save(); open_puzzle(b, places[b.file] or 1); save() end, b ~= bank }
  end
  rows[1] = row
  rows[2] = { { 'Previous', function() kit.close(); open_puzzle(bank, idx - 1); save() end }, { 'How to play', how_to } }
  rows[3] = { { 'Close', kit.close } }
  kit.show({ title = 'Hashi', lines = { (bank and bank.label or '') .. ': puzzle ' .. idx .. ' of ' .. (bank and bank.count or 0) ..
             ', ' .. (bank and solved_count(bank) or 0) .. ' solved.' }, rows = rows, cancel = kit.close })
end

local function in_rect(x, y, rx, ry, rw, rh) return x >= rx and x < rx + rw and y >= ry and y < ry + rh end

local function tap(x, y)
  if kit.tap_modal(x, y) then return end
  for k = 1, #BUTTONS do
    local bx, by, bw, bh = button_rect(k)
    if in_rect(x, y, bx, by, bw, bh) then
      if k == 1 then undo() elseif k == 2 then restart()
      elseif k == 3 then open_puzzle(bank, idx + 1); save() else more() end
      return
    end
  end
  if not grid or solved then return end
  local i = island_at(x, y)
  if i then
    if sel and sel ~= i then
      for e, ed in ipairs(grid.edges) do
        if (ed.a == sel and ed.b == i) or (ed.a == i and ed.b == sel) then sel = nil; cycle(e); return end
      end
      msg = 'Those islands are not in line with open water between.'
    end
    sel = (sel ~= i) and i or nil
    return
  end
  local e = edge_at(x, y)
  if e then sel = nil; cycle(e) end
end

function on_input(c, ev)
  ERR = nil
  local handled = true
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and ev.key == 'back' then
      -- Back acts on its release (the host reads only the up event's answer): it closes a box;
      -- on the board it is left to the host, which offers to exit
      if ev.phase ~= 'up' and ev.phase ~= nil then return end
      if kit.modal() then
        if kit.modal().cancel then kit.modal().cancel() end
      else handled = false end
    elseif ev.type == 'key' and kit.key_accepted(ev) then
      if kit.modal() then
        -- other keys do nothing while a box is open
      elseif ev.key == 'down' or ev.key == 'right' then open_puzzle(bank, idx + 1); save()
      elseif ev.key == 'up' or ev.key == 'left' then open_puzzle(bank, idx - 1); save() end
    end
  end)
  if not ok then ERR = tostring(e) end
  kit.refresh()
  return handled
end

function on_load(c)
  local ok, e = pcall(function()
    load_banks()
    if #banks == 0 then ERR = 'no puzzles in the package'; return end
    load_saved()
  end)
  if not ok then ERR = tostring(e) end
end
function on_leave() pcall(save) end

if rawget(_G, '__TEST') then
  __TEST.api = { banks = function() return banks end, bank = function() return bank end, idx = function() return idx end,
                 grid = function() return grid end, bridges = function() return bridges end, solved = function() return solved end,
                 msg = function() return msg end, center = center, open_puzzle = open_puzzle, set_bridge = set_bridge,
                 button_rect = button_rect, count_at = count_at, done = function() return done end }
end
